ee:message.ee:set-payload:
%dw 2.0
output application/json skipNullOn = "everywhere"
---
{
	basePath: p("zsmart-sapi.base-path"),
	host: p("zsmart-sapi.host"),
	port: p("zsmart-sapi.port"),
	method: "POST",
	path: p('zsmart-sapi.resources.createDispute.path'),
	body: {
		transactionID: payload.transactionId,
		msisdn: payload.msisdn,
		accountNumber: payload.accountNumber,
		partyType: payload.partyType,
		partyCode: payload.partyCode,
		comment: payload.comment,
		charge: payload.charge,
		billId: payload.billId,
		channelCode: payload.channelCode,
		disputeItemExParamList: payload.disputes map ((dispute) -> {
			acctItemID: dispute.acctItemId,
			charge: dispute.charge
		})
	},
	headers: vars.billingHeaders default {
	},
	queryParameters: {
	},
	uriParameters: {
	}
}
